import { test, expect } from '@playwright/test';

const FP_HEADER = { 'x-browser-fingerprint': 'qa-detail-spec-fp-001' };

test.describe('Post Detail & Admin Route Draft E2E', () => {
  test('GET /admin returns SPA HTML and renders Admin Login UI', async ({ page, request }) => {
    const res = await request.get('/admin');
    expect(res.status()).toBe(200);
    expect(res.headers()['content-type'] || '').toContain('text/html');
    const html = await res.text();
    expect(html).not.toBe('Not Found');

    await page.goto('/admin');
    await expect(page.getByText(/管理员登录|社区系统管理后台/i).first()).toBeVisible();
  });

  test('User navigates from feed to post detail page and posts a comment there', async ({ page, request }) => {
    const postText = `Draft Detail Post ${Date.now()}`;
    const createRes = await request.post('/api/v1/posts', {
      headers: FP_HEADER,
      data: { content: postText },
    });
    expect([200, 201]).toContain(createRes.status());
    const { id: postId } = await createRes.json();

    await page.goto('/');
    const main = page.getByRole('main');
    const card = main.locator('article').filter({ hasText: postText }).first();
    await expect(card).toBeVisible();
    await expect(card.getByPlaceholder(/撰写评论|撰写回复/i)).toHaveCount(0);

    await card.getByText(postText).first().click();
    await expect(page).toHaveURL(new RegExp(`/posts/${postId}/?$`));
    await expect(main.getByText(postText).first()).toBeVisible();

    const commentInput = main
      .getByPlaceholder(/撰写评论|撰写回复|评论|回复/i)
      .or(main.getByRole('textbox', { name: /回复|评论/i }))
      .first();
    await expect(commentInput).toBeVisible();

    const commentText = `Detail Page Comment ${Date.now()}`;
    await commentInput.fill(commentText);
    const submitBtn = main
      .locator('form')
      .filter({ has: commentInput })
      .getByRole('button', { name: /回复|发送|提交|评论/i })
      .first();
    await submitBtn.click();

    await expect(main.getByText(commentText).first()).toBeVisible();

    const backBtn = main.getByRole('button', { name: /返回|back/i }).first();
    await expect(backBtn).toBeVisible();
    await backBtn.click();
    await expect(page).toHaveURL(/^https?:\/\/[^/]+\/?$/);
  });
});
